9	/**
10	 * Step of {@code POST /api/owners} that records how many existing owners already share this
11	 * owner's name. {@code namesakeCount} is set to the number of owners present before this create
12	 * whose firstName and lastName both match, compared case-insensitively with collapsed whitespace.
13	 * Runs before {@link SaveOwner}, so the owner being created is not counted against itself.
14	 */
15	public class AssignNamesakeCount {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = normalize(owner.getFirstName());
19	        String lastName = normalize(owner.getLastName());
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (firstName.equals(normalize(existing.getFirstName()))
23	                    && lastName.equals(normalize(existing.getLastName()))) {
24	                count++;
25	            }
26	        }
27	        owner.setNamesakeCount(count);
28	    }
29	
30	    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
31	    private static String normalize(String value) {
32	        if (value == null) {
33	            return "";
34	        }
35	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
36	    }
37	}
