26	    /**
27	     * The householdId a create request maps to: the deterministic id for its {@code lastName} and
28	     * {@code postcode}, or {@code null} when no postcode is supplied (no household).
29	     */
30	    static String forRequest(OwnerFieldsDto request) {
31	        String postcode = request.getPostcode();
32	        if (postcode == null || postcode.isBlank()) {
